MK = {"US": "USA", "GB": "Europe", "DE": "Europe", "CN": "China"}
res = {}
for line in open(inp, encoding="utf-8"):
    r = json.loads(line)
    rid = r["record_id"]
    key = rid.split("-")[2]
    sigs = []
    for t in S.get(key, []):
        kind, sev, summ, q, qen, topic, asp, conf = t[:8]
        if q not in r["text"]:
            print("QUOTE MISSING", rid, q)
        stated = len(t) > 8
        sigs.append({"kind": kind, "severity": sev, "summary": summ, "quote": q,
                     "quote_en": qen or q, "topic_id": topic, "aspect_group": asp,
                     "confidence": conf, "other_suggestion": "",
                     "market": "Europe" if stated else MK.get(r.get("country"), "Rest of World"),
                     "market_basis": "stated" if stated else "inferred"})
    res[rid] = sigs
used = {rid.split("-")[2] for rid in res}
for k in S:
    if k not in used: print("UNUSED", k)
json.dump(res, open(out, "w", encoding="utf-8"), ensure_ascii=False, indent=1)
print(len(res), sum(len(v) for v in res.values()))

